```go
// thresholdsFilePath 返回 config/thresholds.json 的路径。
// 从当前目录向上找 go.mod 定位仓库根，这样无论从哪个目录运行都能找到配置。
func thresholdsFilePath() string {
	dir, err := os.Getwd()
	if err != nil {
		return filepath.Join("config", "thresholds.json")
	}
	for {
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return filepath.Join(dir, "config", "thresholds.json")
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return filepath.Join("config", "thresholds.json")
		}
		dir = parent
	}
}

// loadThresholds 读取并解析阈值配置。
// 文件不存在、读不出来、内容不是 JSON 对象时返回 ok=false。
func loadThresholds(path string) (map[string]int, bool) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, false
	}
	var raw map[string]any
	if err := json.Unmarshal(data, &raw); err != nil || raw == nil {
		return nil, false
	}
	thresholds := make(map[string]int, len(raw))
	for warehouse, value := range raw {
		number, ok := value.(float64)
		if !ok || number != float64(int(number)) {
			continue
		}
		thresholds[warehouse] = int(number)
	}
	return thresholds, true
}
```

