package inventory

import (
	"os"
	"path/filepath"
	"testing"
)

// 这些测试覆盖 issue-001：阈值来自 config/thresholds.json，读不到就回退。

func TestConfiguredWarehouseUsesFileThreshold(t *testing.T) {
	thresholds, ok := loadThresholds(thresholdsFilePath())
	if !ok {
		t.Fatal("仓库自带的 config/thresholds.json 应当能解析")
	}
	if len(thresholds) == 0 {
		t.Fatal("config/thresholds.json 至少要配置一个仓库")
	}
	for warehouse, want := range thresholds {
		if got := LowStockThreshold(warehouse); got != want {
			t.Errorf("LowStockThreshold(%q) = %d, 期望配置值 %d", warehouse, got, want)
		}
	}
}

func TestLoadThresholdsParsesObject(t *testing.T) {
	path := filepath.Join(t.TempDir(), "thresholds.json")
	if err := os.WriteFile(path, []byte(`{"xian": 7}`), 0o644); err != nil {
		t.Fatal(err)
	}
	got, ok := loadThresholds(path)
	if !ok {
		t.Fatal("合法 JSON 对象应当解析成功")
	}
	if got["xian"] != 7 {
		t.Fatalf("loadThresholds[xian] = %d, 期望 7", got["xian"])
	}
}

func TestLoadThresholdsFallsBack(t *testing.T) {
	dir := t.TempDir()
	cases := map[string]string{
		"array.json":  `[1, 2, 3]`,
		"string.json": `"nope"`,
		"number.json": `42`,
		"null.json":   `null`,
		"broken.json": `{oops`,
	}
	for name, content := range cases {
		path := filepath.Join(dir, name)
		if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
			t.Fatal(err)
		}
		if _, ok := loadThresholds(path); ok {
			t.Errorf("loadThresholds(%s) ok=true, 期望回退", name)
		}
	}
	if _, ok := loadThresholds(filepath.Join(dir, "missing.json")); ok {
		t.Error("文件不存在时应当回退")
	}
}
```

